This improves posix compliance of the file system.

Consider the following file:
```C
#include <stdio.h>
#include <unistd.h>
#include <assert.h>
#include <fcntl.h>
#include <string.h>
#include <sys/stat.h>

static void create_file(const char *path, const char *buffer, int mode) {
  printf("creating: %s\n", path);
  int fd = open(path, O_WRONLY | O_CREAT | O_EXCL, mode);
  assert(fd >= 0);

  int err = write(fd, buffer, sizeof(char) * strlen(buffer));
  assert(err ==  (sizeof(char) * strlen(buffer)));

  close(fd);
}

int main() {
    create_file("file", "test", 0555);
    struct stat buf1;
    stat("file", &buf1);
    sleep(1);
    chmod("file", 0777);
    struct stat buf2;
    stat("file", &buf2);
    printf("delta mtime: %ld\n", buf2.st_atim.tv_sec - buf1.st_atim.tv_sec);
    unlink("file");
}
```
Compiling and running with `gcc` vs `emcc` gives different output because the chmod updated the mtime of the file in Emscripten but not in linux: 
```
$ gcc a.c
$ ./a.c
creating: file
delta mtime: 0
$ emcc a.c
$ node a.out.js
creating: file
delta mtime: 1
````

